// Classes des Îles du Vent (pirates, Antilles, 1716) : dix classes, deux sous-classes chacune.
// Caractéristiques du genre : 0 Force, 1 Adresse, 2 Endurance, 3 Savoir, 4 Instinct, 5 Présence.
// Aucun sort ni aucun pouvoir surnaturel : des métiers de bord, des armes à un coup, le Moral du navire et la Chance (section « Le navire et son Moral » de iles-regles.ts).
// Les pouvoirs marqués « Coup de main » coûtent 1 point de Moral au navire ; ces classes ont toutes le passif « Le navire compte ».
// Tirer, c'est recharger : une arme à feu tire un seul coup (passif « Un coup, puis recharger »).
// Les niveaux élevés donnent des relations et des coups de main de plus en plus audacieux, jamais des surhommes.
// Les textes sont lus par les joueurs : aucun secret du canon (shared/canon/pirates.ts) ici.
import type { ActionType, CharacterClass, Power, Recharge, Subclass } from "./rules";

const P = (level: number, name: string, action: ActionType, recharge: Recharge, effect: string, extra: Partial<Power> = {}): Power => ({ level, name, action, recharge, effect, ...extra });
const S = (id: string, name: string, pitch: string, description: string, powers: Power[]): Subclass => ({ id, name, pitch, description, powers });

/** Un grand pouvoir qui mobilise l'équipage : il coûte du Moral. */
const COUP = " Coup de main : coûte 1 point de Moral au navire (règle du Moral).";

/** DD des pouvoirs qui demandent une sauvegarde. */
const DD = (stat: string) => ` DD de la sauvegarde : 8 + ta maîtrise + ton modificateur de ${stat}.`;

const RECHARGE_COMMUN =
  "Une arme à feu tire un seul coup, puis se recharge : recharger prend une action entière (voir les armes de 1715). Dégainer une arme chargée est une interaction d'objet. Sur un 1 naturel au d20, l'arme fait long feu : l'attaque rate et l'arme est à amorcer de nouveau. Sur un ennemi tombé, tu pilles 1d6 charges.";

const NAVIRE_COMMUN =
  "Un pouvoir marqué « Coup de main » coûte 1 point de Moral au navire : un seul coup de main par scène pour tout le navire, et aucun quand le Moral est à 1 ou à 0. Un coup de main réussi ne rend pas le Moral.";

const STYLE_TIR = "Choisis : Défense (+1 CA), Duel (+2 dégâts avec une arme à une main et rien dans l'autre), Tir (+2 aux attaques à distance) ou Deux armes (ajoute ton modificateur aux dégâts de la seconde arme).";
const STYLE_CORPS = "Choisis : Défense (+1 CA), Duel (+2 dégâts avec une arme à une main), Arme à deux mains (relance les 1 et les 2 aux dégâts) ou Tir (+2 aux attaques à distance).";

const MORT_DUR = "Avantage aux jets contre la mort. Quand tu te stabilises, tu te relèves avec 1 PV.";

